// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAttachmentLink A short-lived link to download the file. Needs to read its channel.
	// (GET /api/v1/attachments/{attachmentId})
	GetAttachmentLink(w http.ResponseWriter, r *http.Request, attachmentId openapi_types.UUID)
	// ClaimGuestAccount Turn this guest into a full account. Needs a guest session.
	// (POST /api/v1/auth/claim)
	ClaimGuestAccount(w http.ResponseWriter, r *http.Request)
	// Login Start a session for an existing account.
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End this session. Needs a session.
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetCurrentUser The account of this session. Needs a session.
	// (GET /api/v1/auth/me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password. Needs a session.
	// (POST /api/v1/auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// Register Create an account and start a session.
	// (POST /api/v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// DeleteChannel Delete a channel with its messages and attachments. Admin or owner.
	// (DELETE /api/v1/channels/{channelId})
	DeleteChannel(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// GetChannel One channel. Needs membership in its server.
	// (GET /api/v1/channels/{channelId})
	GetChannel(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// UpdateChannel Rename a channel, change its topic or its write access. Admin or owner.
	// (PATCH /api/v1/channels/{channelId})
	UpdateChannel(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// UploadAttachment Upload a file for a message in this channel. Needs the right to write and to attach files.
	// (POST /api/v1/channels/{channelId}/attachments)
	UploadAttachment(w http.ResponseWriter, r *http.Request, channelId ChannelId, params UploadAttachmentParams)
	// ListMessages A page of history, newest first. Needs membership in the server.
	// (GET /api/v1/channels/{channelId}/messages)
	ListMessages(w http.ResponseWriter, r *http.Request, channelId ChannelId, params ListMessagesParams)
	// SendMessage Send a message. Needs the right to write in the channel.
	// (POST /api/v1/channels/{channelId}/messages)
	SendMessage(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// MarkChannelRead Move the read cursor of this channel. Needs membership.
	// (PUT /api/v1/channels/{channelId}/read)
	MarkChannelRead(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// CreateChannelVoiceToken A LiveKit token for this voice channel. Needs membership in its server.
	// (POST /api/v1/channels/{channelId}/voice-token)
	CreateChannelVoiceToken(w http.ResponseWriter, r *http.Request, channelId ChannelId)
	// ListConversations Your conversations, the liveliest first. Needs a session.
	// (GET /api/v1/conversations)
	ListConversations(w http.ResponseWriter, r *http.Request)
	// StartConversation Open a conversation with one or more people. Needs a session.
	// (POST /api/v1/conversations)
	StartConversation(w http.ResponseWriter, r *http.Request)
	// GetConversation One conversation you are in.
	// (GET /api/v1/conversations/{conversationId})
	GetConversation(w http.ResponseWriter, r *http.Request, conversationId openapi_types.UUID)
	// ListDevices The devices of this account. Needs a session.
	// (GET /api/v1/devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// RegisterDevice Register this device and its public keys. Needs a session.
	// (POST /api/v1/devices)
	RegisterDevice(w http.ResponseWriter, r *http.Request)
	// RevokeDevice Forget one of your devices and its pending keys. Needs a session.
	// (DELETE /api/v1/devices/{deviceId})
	RevokeDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath)
	// GetKeyBundle The keys to start a session with this device. Needs a session.
	// (GET /api/v1/devices/{deviceId}/key-bundle)
	GetKeyBundle(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath)
	// UploadOneTimeKeys Add one-time keys to your device. Needs a session.
	// (POST /api/v1/devices/{deviceId}/one-time-keys)
	UploadOneTimeKeys(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath)
	// CountOneTimeKeys How many one-time keys your device still has. Needs a session.
	// (GET /api/v1/devices/{deviceId}/one-time-keys/count)
	CountOneTimeKeys(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath)
	// AcknowledgeSecretEnvelope Delete a delivered envelope. Only its recipient may.
	// (DELETE /api/v1/envelopes/{envelopeId})
	AcknowledgeSecretEnvelope(w http.ResponseWriter, r *http.Request, envelopeId openapi_types.UUID, params AcknowledgeSecretEnvelopeParams)
	// AcceptInvite Join the server behind the link. Needs a session.
	// (POST /api/v1/invites/{code}/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request, code InviteCode)
	// JoinAsGuest Enter as a guest, by name alone. No account, no session needed.
	// (POST /api/v1/invites/{code}/guest)
	JoinAsGuest(w http.ResponseWriter, r *http.Request, code InviteCode)
	// PreviewInvite What this link leads to. No session needed.
	// (GET /api/v1/invites/{code}/preview)
	PreviewInvite(w http.ResponseWriter, r *http.Request, code InviteCode)
	// RevokeInvite Revoke an invite link. Admin or owner.
	// (DELETE /api/v1/invites/{inviteId})
	RevokeInvite(w http.ResponseWriter, r *http.Request, inviteId openapi_types.UUID)
	// DeleteMessage Delete your own message.
	// (DELETE /api/v1/messages/{messageId})
	DeleteMessage(w http.ResponseWriter, r *http.Request, messageId MessageId)
	// EditMessage Edit your own message.
	// (PATCH /api/v1/messages/{messageId})
	EditMessage(w http.ResponseWriter, r *http.Request, messageId MessageId)
	// RemoveReaction Take your reaction back.
	// (DELETE /api/v1/messages/{messageId}/reactions/{emoji})
	RemoveReaction(w http.ResponseWriter, r *http.Request, messageId MessageId, emoji string)
	// AddReaction React to a message. Needs the right to write in the channel.
	// (PUT /api/v1/messages/{messageId}/reactions/{emoji})
	AddReaction(w http.ResponseWriter, r *http.Request, messageId MessageId, emoji string)
	// ListSecretChats The secret chats of this device. Needs a session.
	// (GET /api/v1/secret-chats)
	ListSecretChats(w http.ResponseWriter, r *http.Request, params ListSecretChatsParams)
	// StartSecretChat Open a secret chat with one device of one person. Needs a session.
	// (POST /api/v1/secret-chats)
	StartSecretChat(w http.ResponseWriter, r *http.Request, params StartSecretChatParams)
	// LeaveSecretChat Delete this secret chat for this device and forget it on the server.
	// (DELETE /api/v1/secret-chats/{secretChatId})
	LeaveSecretChat(w http.ResponseWriter, r *http.Request, secretChatId openapi_types.UUID, params LeaveSecretChatParams)
	// GetSecretChat One secret chat this device takes part in.
	// (GET /api/v1/secret-chats/{secretChatId})
	GetSecretChat(w http.ResponseWriter, r *http.Request, secretChatId openapi_types.UUID, params GetSecretChatParams)
	// ListSecretEnvelopes Ciphertext waiting for this device, oldest first.
	// (GET /api/v1/secret-chats/{secretChatId}/envelopes)
	ListSecretEnvelopes(w http.ResponseWriter, r *http.Request, secretChatId openapi_types.UUID, params ListSecretEnvelopesParams)
	// SendSecretEnvelope Hand one ciphertext envelope to the server.
	// (POST /api/v1/secret-chats/{secretChatId}/envelopes)
	SendSecretEnvelope(w http.ResponseWriter, r *http.Request, secretChatId openapi_types.UUID, params SendSecretEnvelopeParams)
	// ListUserBlocks The accounts you blocked. Needs a session.
	// (GET /api/v1/users/me/blocks)
	ListUserBlocks(w http.ResponseWriter, r *http.Request)
	// UnblockUser Unblock an account. Needs a session.
	// (DELETE /api/v1/users/me/blocks/{userId})
	UnblockUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// BlockUser Block an account. Needs a session.
	// (PUT /api/v1/users/me/blocks/{userId})
	BlockUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// GetDmPolicy Who may start a direct conversation with you. Needs a session.
	// (GET /api/v1/users/me/dm-policy)
	GetDmPolicy(w http.ResponseWriter, r *http.Request)
	// SetDmPolicy Choose who may start a direct conversation with you. Needs a session.
	// (PUT /api/v1/users/me/dm-policy)
	SetDmPolicy(w http.ResponseWriter, r *http.Request)
	// ListUserDevices The public keys of another person's devices. Needs a session.
	// (GET /api/v1/users/{userId}/devices)
	ListUserDevices(w http.ResponseWriter, r *http.Request, userId UserId)
	// ListWorkspaces The servers this account belongs to, with its role in each. Needs a session.
	// (GET /api/v1/workspaces)
	ListWorkspaces(w http.ResponseWriter, r *http.Request)
	// CreateWorkspace Create a server. Needs a session.
	// (POST /api/v1/workspaces)
	CreateWorkspace(w http.ResponseWriter, r *http.Request)
	// DeleteWorkspace Delete a server with everything in it. Owner only.
	// (DELETE /api/v1/workspaces/{workspaceId})
	DeleteWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// GetWorkspace One server and the caller's role in it. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId})
	GetWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateWorkspace Change the name, the description or the member permissions of a server. Admin or owner.
	// (PATCH /api/v1/workspaces/{workspaceId})
	UpdateWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListWorkspaceBans Who is banned from this server. Admin or owner.
	// (GET /api/v1/workspaces/{workspaceId}/bans)
	ListWorkspaceBans(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UnbanWorkspaceMember Lift a ban. Admin or owner.
	// (DELETE /api/v1/workspaces/{workspaceId}/bans/{userId})
	UnbanWorkspaceMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// BanWorkspaceMember Ban someone from a server. Admin or owner.
	// (PUT /api/v1/workspaces/{workspaceId}/bans/{userId})
	BanWorkspaceMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// ListChannels Channels of a server, in their order. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId}/channels)
	ListChannels(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateChannel Create a channel. Admin or owner, or a member when the server allows it.
	// (POST /api/v1/workspaces/{workspaceId}/channels)
	CreateChannel(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ReorderChannels Set the order of the channels. Admin or owner.
	// (PUT /api/v1/workspaces/{workspaceId}/channels/order)
	ReorderChannels(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// DeleteWorkspaceIcon Remove the icon of a server. Admin or owner.
	// (DELETE /api/v1/workspaces/{workspaceId}/icon)
	DeleteWorkspaceIcon(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UploadWorkspaceIcon Set the icon of a server. Admin or owner.
	// (PUT /api/v1/workspaces/{workspaceId}/icon)
	UploadWorkspaceIcon(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListInvites Invite links of a server. Admin or owner.
	// (GET /api/v1/workspaces/{workspaceId}/invites)
	ListInvites(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateInvite Create an invite link. Admin or owner, or a member when the server allows it.
	// (POST /api/v1/workspaces/{workspaceId}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListWorkspaceMembers Members of a server and their roles. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId}/members)
	ListWorkspaceMembers(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// RemoveWorkspaceMember Remove a member. Admin or owner; anyone may remove themselves.
	// (DELETE /api/v1/workspaces/{workspaceId}/members/{userId})
	RemoveWorkspaceMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// SetWorkspaceMemberRole Change a member's role. Owner only.
	// (PATCH /api/v1/workspaces/{workspaceId}/members/{userId})
	SetWorkspaceMemberRole(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// ListUnread Unread counts for every channel of a server. Needs membership.
	// (GET /api/v1/workspaces/{workspaceId}/unread)
	ListUnread(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// GetLiveness Liveness probe — the process is running.
	// (GET /healthz)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetReadiness Readiness probe — the instance can serve traffic.
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
}

